content:
:root {
  --primary-color: #2563eb;
  --primary-hover: #1d4ed8;
  --bg-color: #f8fafc;
  --card-bg: #ffffff;
  --text-main: #1e293b;
  --text-muted: #64748b;
  --border-color: #e2e8f0;
  --radius: 12px;
  --shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
  --table-header-bg: #f1f5f9;
  --history-item-bg: #f8fafc;
}

@media (prefers-color-scheme: dark) {
  :root {
    --primary-color: #3b82f6;
    --primary-hover: #60a5fa;
    --bg-color: #0f172a;
    --card-bg: #1e293b;
    --text-main: #f8fafc;
    --text-muted: #94a3b8;
    --border-color: #334155;
    --shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.3), 0 2px 4px -1px rgba(0, 0, 0, 0.18);
    --table-header-bg: #334155;
    --history-item-bg: #0f172a;
  }
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  line-height: 1.5;
  padding: 20px;
}

/* スクロールバーのスタイリング */
::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

::-webkit-scrollbar-track {
  background: var(--bg-color);
}

::-webkit-scrollbar-thumb {
  background: var(--border-color);
  border-radius: 4px;
}

::-webkit-scrollbar-thumb:hover {
  background: var(--text-muted);
}

.app-container {
  max-width: 800px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.header {
  text-align: center;
  margin-bottom: 8px;
}

.title {
  font-size: 2rem;
  font-weight: 700;
  color: var(--text-main);
  margin-bottom: 8px;
}

.subtitle {
  font-size: 1rem;
  color: var(--text-muted);
}

.card {
  background-color: var(--card-bg);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 24px;
  box-shadow: var(--shadow);
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-bottom: 16px;
}

.form-group:last-child {
  margin-bottom: 0;
}

.label {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-main);
}

.input,
.select {
  width: 100%;
  padding: 10px 14px;
  font-size: 1rem;
  border: 1px solid var(--border-color);
  border-radius: 8px;
  background-color: var(--card-bg);
  color: var(--text-main);
  transition: border-color 0.2s, box-shadow 0.2s;
}

.input:focus,
.select:focus {
  outline: 2px solid var(--primary-color);
  outline-offset: 2px;
  border-color: var(--primary-color);
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.25);
}

.result-section {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.result-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 16px;
}

.result-card {
  background-color: var(--card-bg);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 16px;
  box-shadow: var(--shadow);
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.unit-name {
  font-size: 0.875rem;
  color: var(--text-muted);
  font-weight: 500;
}

.unit-value {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--primary-color);
  word-break: break-all;
}

.table-section {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
  font-size: 0.95rem;
}

.table th,
.table td {
  padding: 10px 12px;
  border-bottom: 1px solid var(--border-color);
}

.table th {
  font-weight: 600;
  color: var(--text-main);
  background-color: var(--table-header-bg);
}

.table tr:last-child td {
  border-bottom: none;
}

.history-section {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.history-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
  max-height: 200px;
  overflow-y: auto;
}

.history-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 12px;
  background-color: var(--history-item-bg);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  font-size: 0.9rem;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 8px 16px;
  font-size: 0.9rem;
  font-weight: 600;
  border-radius: 8px;
  border: none;
  cursor: pointer;
  background-color: var(--primary-color);
  color: #fff;
  transition: background-color 0.2s;
}

.btn:focus {
  outline: 2px solid var(--primary-color);
  outline-offset: 2px;
}

.btn:hover {
  background-color: var(--primary-hover);
}

.btn-secondary {
  background-color: transparent;
  color: var(--text-muted);
  border: 1px solid var(--border-color);
}

.btn-secondary:hover {
  background-color: var(--table-header-bg);
  color: var(--text-main);
}

@media (max-width: 600px) {
  body {
    padding: 12px;
  }
  .title {
    font-size: 1.5rem;
  }
  .result-grid {
    grid-template-columns: 1fr;
  }
}

/**
 * 単位の種類を表す型
 */
export type UnitType = 'mm' | 'cm' | 'm' | 'km' | 'in' | 'ft';

/**
 * 長さの変換履歴を表すインターフェース
 */
export interface ConversionHistory {
  id: string;
  value: number;
  from: UnitType;
  timestamp: string;
}

/**
 * 互換性のためのエイリアス
 */
export type LengthConversionHistory = ConversionHistory;

import { UnitType } from '../types';

/**
 * サポートされている単位の配列
 */
export const UNITS: UnitType[] = ['mm', 'cm', 'm', 'km', 'in', 'ft'];

export const unitLabels: Record<UnitType, string> = {
  mm: 'ミリメートル (mm)',
  cm: 'センチメートル (cm)',
  m: 'メートル (m)',
  km: 'キロメートル (km)',
  in: 'インチ (in)',
  ft: 'フィート (ft)',
};

export const unitSymbols: Record<UnitType, string> = {
  mm: 'mm',
  cm: 'cm',
  m: 'm',
  km: 'km',
  in: 'in',
  ft: 'ft',
};

// メートルを基準とした換算係数
const toMetersRates: Record<UnitType, number> = {
  mm: 0.001,
  cm: 0.01,
  m: 1,
  km: 1000,
  in: 0.0254,
  ft: 0.3048,
};

/**
 * 小数点以下の丸め処理を行うヘルパー関数
 */
export function roundNumber(value: number, decimals: number = 6): number {
  const factor = Math.pow(10, decimals);
  return Math.round(value * factor) / factor;
}

export function convertLength(value: number, from: UnitType, to: UnitType): number {
  if (isNaN(value) || value < 0) return 0;
  const meters = value * toMetersRates[from];
  const result = meters / toMetersRates[to];
  return roundNumber(result);
}

export function convertAll(value: number, from: UnitType): Record<UnitType, number> {
  if (isNaN(value) || value < 0) {
    const zeroResult = {} as Record<UnitType, number>;
    UNITS.forEach((unit) => {
      zeroResult[unit] = 0;
    });
    return zeroResult;
  }

  const result = {} as Record<UnitType, number>;

  UNITS.forEach((unit) => {
    result[unit] = convertLength(value, from, unit);
  });

  return result;
}

import { ChangeEvent, useState, useEffect } from 'react';
import { UnitType } from '../types';
import { unitLabels, UNITS } from '../utils/converter';

interface ConverterCardProps {
  value: number;
  unit: UnitType;
  onValueChange: (value: number) => void;
  onUnitChange: (unit: UnitType) => void;
}

export default function ConverterCard({
  value,
  unit,
  onValueChange,
  onUnitChange,
}: ConverterCardProps) {
  const units = UNITS;
  const [inputValue, setInputValue] = useState(value.toString());

  useEffect(() => {
    setInputValue(value.toString());
  }, [value]);

  const handleInputChange = (e: ChangeEvent<HTMLInputElement>) => {
    const valStr = e.target.value;
    setInputValue(valStr);
    const val = parseFloat(valStr);
    if (!isNaN(val)) {
      onValueChange(val);
    } else if (valStr === '') {
      onValueChange(0);
    }
  };

  const handleSelectChange = (e: ChangeEvent<HTMLSelectElement>) => {
    onUnitChange(e.target.value as UnitType);
  };

  return (
    <div className="card">
      <div className="form-group">
        <label className="label" htmlFor="length-value">
          変換する値
        </label>
        <input
          id="length-value"
          type="number"
          className="input"
          value={inputValue}
          onChange={handleInputChange}
          placeholder="値を入力してください"
          step="any"
          aria-label="変換する値"
          aria-describedby="length-value-desc"
        />
        <span id="length-value-desc" style={{ display: 'none' }}>
          数値を入力して単位を変換します
        </span>
      </div>

      <div className="form-group" style={{ marginTop: '16px' }}>
        <label className="label" htmlFor="length-unit">
          単位
        </label>
        <select
          id="length-unit"
          className="select"
          value={unit}
          onChange={handleSelectChange}
          aria-label="変換元の単位"
        >
          {units.map((u) => (
            <option key={u} value={u}>
              {unitLabels[u]}
            </option>
          ))}
        </select>
      </div>
    </div>
  );
}

import { useState } from 'react';
import { UnitType } from '../types';
import { convertAll, unitLabels, UNITS } from '../utils/converter';

interface ResultGridProps {
  value: number;
  from: UnitType;
}

export default function ResultGrid({ value, from }: ResultGridProps) {
  const results = convertAll(value, from);
  const units = UNITS;
  const [copiedUnit, setCopiedUnit] = useState<UnitType | null>(null);

  const handleCopy = (unit: UnitType, val: number) => {
    navigator.clipboard.writeText(val.toString());
    setCopiedUnit(unit);
    setTimeout(() => {
      setCopiedUnit(null);
    }, 2000);
  };

  return (
    <div className="result-section">
      <div className="result-grid">
        {units.map((unit) => {
          const val = results[unit];
          return (
            <div
              key={unit}
              className="result-card"
              onClick={() => handleCopy(unit, val)}
              style={{ cursor: 'pointer', position: 'relative' }}
              title="クリックしてコピー"
            >
              <span className="unit-name">{unitLabels[unit]}</span>
              <span className="unit-value">
                {val.toLocaleString(undefined, {
                  maximumFractionDigits: 6,
                })}
              </span>
              {copiedUnit === unit && (
                <span
                  style={{
                    fontSize: '0.75rem',
                    color: 'var(--primary-color)',
                    position: 'absolute',
                    top: '8px',
                    right: '8px',
                    fontWeight: 600,
                  }}
                >
                  コピーしました！
                </span>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { UnitType, ConversionHistory } from './types';
import { unitLabels } from './utils/converter';
import ConverterCard from './components/ConverterCard';
import ResultGrid from './components/ResultGrid';

export default function App() {
  const [value, setValue] = useState<number>(1);
  const [fromUnit, setFromUnit] = useState<UnitType>('m');
  const [history, setHistory] = useState<ConversionHistory[]>(() => {
    const saved = localStorage.getItem('length_conversion_history');
    if (saved) {
      try {
        return JSON.parse(saved);
      } catch {
        return [];
      }
    }
    return [];
  });

  useEffect(() => {
    localStorage.setItem('length_conversion_history', JSON.stringify(history));
  }, [history]);

  useEffect(() => {
    if (isNaN(value) || value <= 0) return;
    const timer = setTimeout(() => {
      const newItem: ConversionHistory = {
        id: typeof crypto !== 'undefined' && crypto.randomUUID 
          ? crypto.randomUUID() 
          : Math.random().toString(36).substring(2, 9),
        value,
        from: fromUnit,
        timestamp: new Date().toLocaleTimeString(),
      };
      setHistory((prev) => [newItem, ...prev.filter(item => !(item.value === value && item.from === fromUnit))].slice(0, 10));
    }, 1000);

    return () => clearTimeout(timer);
  }, [value, fromUnit]);

  const handleClearHistory = () => {
    setHistory([]);
  };

  const referenceTableData = [
    { name: '1 mm', mm: 1, cm: 0.1, m: 0.001, in: 0.03937 },
    { name: '1 cm', mm: 10, cm: 1, m: 0.01, in: 0.3937 },
    { name: '1 m', mm: 1000, cm: 100, m: 1, in: 39.3701 },
    { name: '1 km', mm: 1000000, cm: 100000, m: 1000, in: 39370.1 },
    { name: '1 インチ (in)', mm: 25.4, cm: 2.54, m: 0.0254, in: 1 },
    { name: '1 フィート (ft)', mm: 304.8, cm: 30.48, m: 0.3048, in: 12 },
  ];

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="title">長さ単位変換ツール</h1>
        <p className="subtitle">
          ミリメートル、センチメートル、メートル、キロメートル、インチ、フィートを瞬時に相互変換します。
        </p>
      </header>

      <ConverterCard
        value={value}
        unit={fromUnit}
        onValueChange={setValue}
        onUnitChange={setFromUnit}
      />

      <ResultGrid value={value} from={fromUnit} />

      <section className="card table-section">
        <h2 className="label">よく使う単位の早見表</h2>
        <div style={{ overflowX: 'auto' }}>
          <table className="table">
            <thead>
              <tr>
                <th>基準単位</th>
                <th>mm</th>
                <th>cm</th>
                <th>m</th>
                <th>インチ (in)</th>
              </tr>
            </thead>
            <tbody>
              {referenceTableData.map((row, index) => (
                <tr key={index}>
                  <td><strong>{row.name}</strong></td>
                  <td>{row.mm}</td>
                  <td>{row.cm}</td>
                  <td>{row.m}</td>
                  <td>{row.in}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </section>

      {history.length > 0 && (
        <section className="card history-section">
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <h2 className="label">変換履歴</h2>
            <button className="btn btn-secondary" onClick={handleClearHistory} style={{ padding: '4px 8px', fontSize: '0.8rem' }}>
              履歴をクリア
            </button>
          </div>
          <ul className="history-list">
            {history.map((item) => (
              <li key={item.id} className="history-item">
                <span>
                  <strong>{item.value}</strong> {unitLabels[item.from]}
                </span>
                <span style={{ color: 'var(--text-muted)', fontSize: '0.8rem' }}>
                  {item.timestamp}
                </span>
              </li>
            ))}
          </ul>
        </section>
      )}
    </div>
  );
}
